head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[xml > M > parse]<br/>XML 문자열을 XML Document 객체로 파싱하여 반환합니다.",
    "validation" : [
        "info(필수) 파라미터로 파싱할 XML 문자열을 설정할 수 있어야 합니다.",
        "info(필수) 파라미터에 XML Document 또는 XML Element 를 전달하면 직렬화한 후 다시 파싱하여 새로운 XML Document 객체를 생성해야 합니다.",
        "info(필수) 파라미터에 빈 문자열을 전달하면 null 을 반환해야 합니다.",
        "namespace(선택) 파라미터로 네임스페이스의 파싱 여부를 true/false 로 설정할 수 있어야 합니다. (IE ActiveX 환경에서만 동작)",
        "namespace(선택) 파라미터 생략 시 false 로 동작해야 합니다.",
        "파싱된 XML Document 객체를 반환해야 합니다.",
        "파싱 오류 또는 예외 발생 시 null 을 반환해야 합니다.",
        "info 파라미터에 전달한 문자열의 첫 문자가 '<' 가 아니면 자동으로 태그로 감싸서 파싱해야 합니다.",
    ]
}

scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.btn_parse_onclick = function () {
    var infoType = par_info.getValue();
    var namespace = par_namespace.getValue();

    var info;
    var infoDesc = "";
    if (infoType === "xmlString") {
        info = "<data><title>WebSquare</title></data>";
        infoDesc = "XML 문자열";
    } else if (infoType === "nsString") {
        info = "<w2:data xmlns:w2='http://www.inswave.com/websquare'><w2:title>WebSquare</w2:title></w2:data>";
        infoDesc = "네임스페이스 XML 문자열";
    } else if (infoType === "document") {
        info = WebSquare.xml.parse("<data><title>WebSquare</title></data>");
        infoDesc = "XML Document";
    } else if (infoType === "element") {
        var tmpDoc = WebSquare.xml.parse("<data><title>WebSquare</title></data>");
        info = WebSquare.xml.findNode(tmpDoc, "data");
        infoDesc = "XML Element";
    } else if (infoType === "empty") {
        info = "";
        infoDesc = "빈 문자열";
    } else if (infoType === "noTag") {
        info = "data";
        infoDesc = "태그명 문자열(data)";
    } else if (infoType === "invalid") {
        info = "<data><title>unclosed";
        infoDesc = "잘못된 XML";
    }

    var result;
    if (namespace === "") {
        result = WebSquare.xml.parse(info);
    } else {
        result = WebSquare.xml.parse(info, namespace === "true");
    }

    wf_body_bottom.getObj("scwin").setReturnValue("parse(" + infoDesc + (namespace ? ", " + namespace : "") + ")");

    if (result !== null) {
        wf_body_bottom.getObj("scwin").setReturnValue("결과 : XML Document");
        wf_body_bottom.getObj("scwin").setReturnValue("내용 : " + WebSquare.xml.serialize(result));
    } else {
        wf_body_bottom.getObj("scwin").setReturnValue("결과 : null");
    }
}
